        ["machine.core:carbon_unloader"] = ("puerto de carbono", "carbon port"),
        ["recipe.core:crack_ice"] = ("craquear hielo", "crack ice"),
        ["learn.defence"] = ("Los Remnant atacan módulos enteros y, al caer uno, pierdes lo que hay dentro; si cae el núcleo de una estación se pierde toda. Construye un módulo de defensa, pon torretas con munición por cinta (y muros delante) y un taller con taller de reparación.",
                             "The Remnant attack whole modules, and when one falls you lose everything inside it; if a station core falls the whole station is lost. Build a defence module, put turrets in it fed with ammo by belt (and walls in front) and a repair bay in a workshop."),
        ["learn.noFuel"] = ("Te queda poco hidrógeno y el reactor de tu nave lo gasta. Se hace con hielo: mina hielo en el sistema inicial, construye un craqueador de hidrógeno en el taller y llévale el hielo con un puerto de hielo; un depósito devuelve el hidrógeno a tu bodega.",
                            "Your hydrogen is running low and your ship's reactor burns it. It is made from ice: mine ice in the home system, build a hydrogen cracker in the workshop and feed it ice with an ice port; a depot returns the hydrogen to your hold."),
        ["learn.lowPower"] = ("Sin hidrógeno solo queda un hilo de energía de emergencia: las máquinas y los motores van muy lentos. Mina hielo, conviértelo en hidrógeno y recupera la potencia.",
                              "Without hydrogen only a trickle of emergency power is left: machines and engines crawl. Mine ice, crack it into hydrogen and restore full power."),
        ["obj.makeFuel"] = ("Fabrica hidrógeno", "Make hydrogen"),
        ["obj.makeFuel.hint"] = ("El reactor quema hidrógeno de tu bodega. En el menú B pon un Craqueador (categoría Producción) en el taller y un puerto de hielo (categoría Logística) que le lleve el hielo que mines a mano en el sistema inicial: el craqueador saca hidrógeno.",
                                 "The reactor burns hydrogen from your hold. In the B menu place a Cracker (Production category) in the workshop and an ice port (Logistics category) to feed it the ice you hand-mine in the home system: the cracker makes hydrogen."),
        ["obj.addModule"] = ("Añade módulos", "Add modules"),
        ["obj.addModule.hint"] = ("Amplía tu nave o tu estación con más módulos (taller, defensa, casco) pegados a una cara: cada tipo permite construir cosas distintas. Una estación necesita su propio módulo Reactor para dar energía.",
                                  "Grow your ship or station with more modules (workshop, defence, hull) touching a face: each kind allows different things to be built. A station needs its own Reactor module for power."),
        ["toast.reject.notEnoughItems"] = ("No tienes los objetos en la bodega", "Not enough items in the hold"),

